  const w2y = Math.cos((y+w1y)*0.013+t*0.17)*10 + Math.sin((x+w1x)*0.011-t*0.14)*9;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 0.0],
