    [380+Math.sin(t*0.38+4)*85, 50+Math.cos(t*0.8+2)*65, 0.065, 2.7, 4.19],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*70, 0.085, 2.0, 5.24],
    [60+Math.sin(t*0.6+3)*60, 120+Math.cos(t*0.4+4)*50, 0.1, 1.6, 0.52],
    [420+Math.cos(t*0.55+2)*50, 100+Math.sin(t*0.65+1)*40, 0.07, 2.2, 2.62]
  ];
  let aS=0, iS=0, wS=0;
