  const reaction=Math.tanh((act-inh*0.65+bg*0.28+spiral+voronoi*0.4+lap*0.3)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45+Math.sin(sx*0.08-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
