  const glow=Math.max(0,1.0-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*30))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*50))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*80))|0
  ];
}
